RN_AMOUNT_EXCL_TAX FROM `project-dea872a4-8550-4cff-a8c`.maplemonk.project_dea872a4_8550_4cff_a8c_unicommerce_returns_fact_items fr LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from `project-dea872a4-8550-4cff-a8c`.maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(fr.marketplace) = lower(mm.marketplace) GROUP BY fr.Marketplace, mm.FINAL_MARKETPLACE, RETURN_COMPLETE_DATE, Marketing_channel UNION ALL SELECT UPPER(coalesce(s_marketplace,ir.MARKETPLACE)) AS Marketplace, UPPER(coalesce(s_marketplace,ir.MARKETPLACE)) FINAL_MARKETPLACE, date(Return_Order_Created_Timestamp) AS RETURN_DATE, UPPER(CHANNEL) AS Marketing_channel, SUM(Quantity) AS TOTAL_RETURNED_QUANTITY, SUM(Forward_Unit_Sale_Price) AS TOTAL_RETURN_AMOUNT, SUM(Forward_Unit_Tax) AS TOTAL_RETURN_TAX, SUM(Forward_Unit_Base_Price) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM MapleMonk.Miniklub_s3_increff_returns_fact_items ir left join ( select reference_code, marketplace s_marketplace, CHANNEL from maplemonk.project_dea872a4_8550_4cff_a8c_sales_consolidated qualify row_number() over(partition by lower(trim(reference_code)) order by 1) = 1 )s on lower(trim(ir.Channel_Parent_Order_ID)) = lower(trim(s.reference_code)) group by 1,2,3,4 ;",
